import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Algorithms → Graph traversals; Minimum spanning trees; Shortest paths (CLRS ch. 20–23). Numbers from lib/study/algo2.ts, checked by script:
 * Square A-B-C-D-A bipartite {A, C} | {B, D}; triangle not (edge B–C). Kahn on A>B, A>C, B>D, C>D, D>E → A B C D E, 2 orders; A>C, B>C, C>D, C>E → 4 orders.
 * SCCs of A>B B>C C>A B>D D>E E>F F>D G>F G>H: {A,B,C}, {D,E,F}, {G}, {H}. Cut vertices of A-B B-C C-A C-D D-E E-F F-D D-G: C, D; bridges C–D, D–G.
 * CLRS MST graph: weight 37; Kruskal keeps G–H 1, C–I 2, F–G 2, A–B 4, C–F 4, C–D 7, A–H 8, D–E 9. Prim from A adds B, H, G, F, C, I, D, E.
 * A-B 1, B-C 2, C-D 1, D-A 2, A-C 3: 8 spanning trees, MST weight 4, 2 MSTs. 4-cycle with equal weights: 4 spanning trees, all minimum.
 * CLRS Dijkstra from s: extraction s y z t x; t 8, x 9, y 5, z 7. CLRS Bellman–Ford: t 2, x 4, y 7, z −2. A>B 1, B>C −2, C>A −1: negative cycle.
 * CLRS Floyd–Warshall final row 1: 0 1 −3 2 −4.
 */
const AL = "/topics/algorithms";

