const bellmanT: Topic = {
  id: "cs.algo.sp.bellman",
  title: "Bellman–Ford and negative cycles",
  blocks: [
    { type: "hook", text: "With edges of weight −4, −2 and −3, Dijkstra can be fooled, but Bellman–Ford relaxes every edge V − 1 times and finds s to z costs −2. One more pass that still improves something proves a negative cycle." },
    { type: "objectives", items: ["Run Bellman–Ford pass by pass.", "Detect negative cycles reachable from the source.", "Know DAG shortest paths and distance-vector routing as relatives."] },
    { type: "intuition", paras: ["A shortest path without cycles uses at most V − 1 edges. After pass i of relaxing every edge, every shortest path of at most i edges is correct. So V − 1 passes suffice.", "If a V-th pass still improves a distance, some path keeps getting cheaper: a negative cycle is reachable, and shortest paths are undefined (−∞).", "Bellman–Ford costs O(VE), slower than Dijkstra but correct with negative edges. It can stop early when a pass changes nothing."], analogyLimit: "Like news passing through a chain of villages: after k rounds, everyone within k hops has heard the best price." },
    { type: "definition", name: "Bellman–Ford", text: "Single source, any weights:", items: ["Repeat V − 1 times: relax every edge.", "Then if any edge still relaxes, report a negative cycle.", "Time O(VE); space O(V).", "Early exit when a pass makes no change.", "DAG shortest paths: relax edges in topological order once: O(V + E), negative weights allowed."] },
    { type: "deep", sections: [
      { h: "Order of relaxation", points: ["The final distances do not depend on edge order, but intermediate passes do.", "A lucky order can finish in one pass; the worst order needs V − 1.", "GATE fixes an edge order and asks distances after pass k.", "SPFA (queue-based) relaxes only edges out of changed vertices."], paras: [] },
      { h: "Distance-vector routing", paras: ["RIP routers run a distributed Bellman–Ford: each router updates its distances from its neighbours' vectors. Without a central view they suffer count-to-infinity when links fail."] },
      { h: "Negative cycles in practice", paras: ["Currency arbitrage: take −log of exchange rates as edge weights; a negative cycle is a profitable sequence of trades."] },
      { h: "Longest paths", paras: ["Longest simple paths are NP-hard in general graphs; negating weights and running Bellman–Ford finds them only when no positive cycle exists, i.e. in DAGs, where topological relaxation is simpler."] },
    ] },
    { type: "walkthrough", steps: ["d[s] = 0, others ∞.", "Pass: relax every edge in the given order.", "Repeat V − 1 passes (or until nothing changes).", "One extra pass: any improvement means a negative cycle."], prompt: { q: "Passes Bellman–Ford needs in the worst case for 5 vertices?", a: "4 (V − 1)." } },
    { type: "figure", id: "bf", caption: "CLRS Bellman–Ford from s.", alt: "Final t 2, x 4, y 7, z −2.", fig: { kind: "matrix", title: "After pass", cols: ["t", "x", "y", "z"], rows: [{ label: "1", cells: [6, 4, 7, 2] }, { label: "2", cells: [2, 4, 7, 2] }, { label: "3", cells: [2, 4, 7, -2], hl: true }, { label: "4", cells: [2, 4, 7, -2] }] } },
    { type: "example", id: "ex1", level: "gate", title: "The CLRS run", given: "s→t 6, s→y 7, t→x 5, t→y 8, t→z −4, x→t −2, y→x −3, y→z 9, z→s 2, z→x 7 (relaxed in this order).", find: "Distances after each pass.",
      steps: [{ say: "Pass 1: t 6, y 7, x 4 (via y), z 2." }, { say: "Pass 2: t = 4 − 2 = 2." }, { say: "Pass 3: z = 2 − 4 = −2; pass 4 changes nothing.", result: "t 2, x 4, y 7, z −2" }],
      answer: "t 2, x 4, y 7, z −2; no negative cycle.",
      check: "Path to z: s → y → x → t → z = 7 − 3 − 2 − 4 = −2." },
    { type: "figure", id: "negc", for: "ex2", caption: "A negative cycle A → B → C → A.", alt: "1 − 2 − 1 = −2.", fig: { kind: "strip", items: [{ label: "A → B", sub: "1", state: "done" }, { label: "B → C", sub: "−2", state: "done" }, { label: "C → A", sub: "−1", state: "done" }, { label: "cycle", sub: "total −2", state: "bad" }] } },
    { type: "example", id: "ex2", level: "gate", title: "Detecting a negative cycle", given: "A→B 1, B→C −2, C→A −1; source A.", find: "What the extra pass shows.",
      steps: [{ say: "Cycle weight 1 − 2 − 1 = −2 < 0." }, { say: "After V − 1 passes some edge still relaxes.", result: "negative cycle" }],
      answer: "Bellman–Ford reports a negative cycle; distances are −∞.",
      check: "Dijkstra would silently report wrong values." },
    { type: "example", id: "ex3", level: "edge", title: "Shortest paths in a DAG", given: "DAG r→s 5, r→t 3, s→t 2, s→x 6, t→x 7, t→y 4, x→y −1, x→z 1, y→z −2; source s.", find: "Distance to z.",
      steps: [{ say: "Topological order r, s, t, x, y, z; relax in that order once." }, { say: "From s: t 2, x 6, y 6 (via t) then 5 (via x), z 3 (via y).", result: "3" }],
      answer: "3, in O(V + E) despite negative weights.",
      check: "This is the CLRS DAG shortest-path example." },
    { type: "lab", lab: "bellman" },
    { type: "faded", title: "Your turn", given: "s→a 4, s→b 5, b→a −3; source s.", steps: [{ say: "Distance to a?", blank: true, answer: "min(4, 5 − 3) = 2." }] },
    { type: "trap", wrong: "Bellman–Ford fails with negative edges.", tempting: "Dijkstra does.", whyWrong: "It handles them; it only fails to define distances when a negative cycle is reachable, and it detects that.", rule: "Negative edges fine; negative cycles detected." },
    { type: "trap", wrong: "V passes are needed.", tempting: "One per vertex.", whyWrong: "Simple paths have at most V − 1 edges; the V-th pass is only the cycle check.", rule: "V − 1 passes + one check." },
    { type: "gate", text: "GATE asks distances after k passes, negative-cycle detection, and complexity comparisons with Dijkstra." },
    { type: "recall", cards: [{ q: "Bellman–Ford time", a: "O(VE)" }, { q: "Passes", a: "V − 1, then one check" }, { q: "DAG shortest paths", a: "Topological order, O(V + E)" }] },
    { type: "check", questions: [
      { id: "bl1", kind: "NAT", marks: 2, q: "CLRS Bellman–Ford: final distance from s to z?", answer: "-2", solution: "s→y→x→t→z." },
      { id: "bl2", kind: "NAT", marks: 1, q: "Worst-case passes for 5 vertices (excluding the check)?", answer: "4", solution: "V − 1." },
      { id: "bl3", kind: "MCQ", marks: 1, q: "A→B 1, B→C −2, C→A −1: Bellman–Ford reports", options: ["Distances 0, 1, −1", "A negative cycle", "No path", "An error"], answer: "B", solution: "Cycle weight −2." },
      { id: "bl4", kind: "NAT", marks: 1, q: "s→a 4, s→b 5, b→a −3: distance to a?", answer: "2", solution: "5 − 3." },
      { id: "bl5", kind: "MSQ", marks: 2, q: "Which are true?", options: ["Bellman–Ford runs in O(VE)", "It handles negative edges", "DAG shortest paths take O(V + E)", "It cannot detect negative cycles"], answer: "A, B, C", solution: "It can." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Algorithms", sub: "Bellman–Ford", href: AL }, { label: "Computer networks", sub: "Distance-vector routing", href: "/study/ip" }, { label: "Topic 3: Floyd–Warshall", sub: "All pairs", href: "/study/shortest-paths" }] },
    { type: "links", prereq: ["Relaxation"], usedIn: ["RIP routing, arbitrage"], cross: ["CN: distance vector"] },
  ],
};

const fwT: Topic = {
  id: "cs.algo.sp.fw",
  title: "All-pairs shortest paths: Floyd–Warshall",
  blocks: [
    { type: "hook", text: "Three nested loops over a 5 × 5 matrix give every shortest distance in the CLRS graph at once, negative edges included: from vertex 1 to 5 the answer is −4. Floyd–Warshall is dynamic programming over which vertices may be used as stops." },
    { type: "objectives", items: ["Run Floyd–Warshall and read intermediate matrices.", "Detect negative cycles from the diagonal.", "Compute transitive closure (Warshall) and compare all-pairs methods."] },
    { type: "intuition", paras: ["Let D⁽ᵏ⁾[i][j] be the shortest i → j distance using only vertices 1 … k as intermediate stops. Either vertex k is not used (D⁽ᵏ⁻¹⁾[i][j]) or the path goes i → k → j (D⁽ᵏ⁻¹⁾[i][k] + D⁽ᵏ⁻¹⁾[k][j]).", "Start from the weight matrix (0 on the diagonal, ∞ for missing edges) and update for k = 1 … n: Θ(n³) time, Θ(n²) space (in place is fine).", "A negative number on the diagonal at the end means a negative cycle through that vertex. Replacing min/+ with OR/AND computes reachability (Warshall's transitive closure)."], analogyLimit: "Like planning flights by first allowing only direct ones, then connections through city 1, then through cities 1 and 2, and so on." },
    { type: "definition", name: "Floyd–Warshall", text: "For n vertices:", items: ["D⁽⁰⁾ = weight matrix (0 diagonal, ∞ if no edge).", "D⁽ᵏ⁾[i][j] = min(D⁽ᵏ⁻¹⁾[i][j], D⁽ᵏ⁻¹⁾[i][k] + D⁽ᵏ⁻¹⁾[k][j]).", "Θ(n³) time, Θ(n²) space.", "Negative weights allowed; D[i][i] < 0 ⇒ negative cycle.", "Warshall: R[i][j] = R[i][j] ∨ (R[i][k] ∧ R[k][j])."] },
    { type: "deep", sections: [
      { h: "All-pairs options", points: ["Floyd–Warshall: Θ(V³), simple, dense graphs, negative edges.", "V × Dijkstra with heaps: O(VE log V), non-negative weights, sparse graphs.", "Johnson: reweight with Bellman–Ford, then V × Dijkstra: O(VE log V) with negative edges.", "V × BFS for unweighted graphs: O(V(V + E))."], paras: [] },
      { h: "Path reconstruction", paras: ["Keep next[i][j] (or pred) and update it whenever going through k is shorter. The path is rebuilt by following next pointers."] },
      { h: "Loop order matters", paras: ["k must be the outermost loop: the DP needs all pairs at stage k − 1 before stage k. Putting k innermost computes something else and is a classic bug."] },
      { h: "Reading one entry", paras: ["GATE sometimes asks a single entry of D⁽ᵏ⁾ for small k: compute only the row and column of k from the previous matrix."] },
    ] },
    { type: "walkthrough", steps: ["Write D⁽⁰⁾ from the edges.", "For k = 1: update every cell through vertex 1.", "Repeat for k = 2 … n.", "Read the final matrix; check the diagonal for negatives."], prompt: { q: "Floyd–Warshall's complexity?", a: "Θ(V³)." } },
    { type: "figure", id: "fw", caption: "CLRS example: final distances.", alt: "Final 5 × 5 matrix.", fig: { kind: "matrix", title: "D⁽⁵⁾", cols: ["1", "2", "3", "4", "5"], rows: [{ label: "1", cells: [0, 1, -3, 2, -4], hl: true }, { label: "2", cells: [3, 0, -4, 1, -1] }, { label: "3", cells: [7, 4, 0, 5, 3] }, { label: "4", cells: [2, -1, -5, 0, -2] }, { label: "5", cells: [8, 5, 1, 6, 0] }] } },
    { type: "example", id: "ex1", level: "gate", title: "The CLRS matrix", given: "1→2 3, 1→3 8, 1→5 −4, 2→4 1, 2→5 7, 3→2 4, 4→1 2, 4→3 −5, 5→4 6.", find: "Shortest distance from 1 to 3 and from 1 to 2.",
      steps: [{ say: "1 → 5 → 4 → 3: −4 + 6 − 5 = −3." }, { say: "1 → 5 → 4 → 3 → 2: −3 + 4 = 1.", result: "−3 and 1" }],
      answer: "d(1, 3) = −3, d(1, 2) = 1; row 1 is 0 1 −3 2 −4.",
      check: "No diagonal entry is negative: no negative cycle." },
    { type: "figure", id: "tc", for: "ex2", caption: "Transitive closure of 1 → 2 → 3, 4 isolated.", alt: "1 reaches 2 and 3.", fig: { kind: "matrix", title: "Reachability", cols: ["1", "2", "3", "4"], rows: [{ label: "1", cells: [1, 1, 1, 0], hl: true }, { label: "2", cells: [0, 1, 1, 0] }, { label: "3", cells: [0, 0, 1, 0] }, { label: "4", cells: [0, 0, 0, 1] }] } },
    { type: "example", id: "ex2", level: "gate", title: "Transitive closure", given: "Edges 1 → 2, 2 → 3; vertex 4 isolated.", find: "Reachability matrix.",
      steps: [{ say: "Through k = 2: 1 reaches 3." }, { say: "No other new pairs.", result: "1 → {2, 3}, 2 → {3}" }],
      answer: "Row 1: 1 1 1 0; row 2: 0 1 1 0; row 3: 0 0 1 0; row 4: 0 0 0 1.",
      check: "Taking each vertex as reaching itself puts 1s on the diagonal." },
    { type: "example", id: "ex3", level: "edge", title: "Which all-pairs algorithm", given: "V = 1000 sparse (E = 5000), non-negative weights; and V = 300 dense with negative edges.", find: "Choice for each.",
      steps: [{ say: "Sparse, non-negative: V × Dijkstra ≈ 1000 × 6000 × 10 = 6 × 10⁷ < 10⁹." }, { say: "Dense with negative edges: Floyd–Warshall, 2.7 × 10⁷.", result: "different choices" }],
      answer: "Repeated Dijkstra for the first; Floyd–Warshall for the second.",
      check: "Johnson's algorithm would also handle the second." },
    { type: "lab", lab: "fw" },
    { type: "faded", title: "Your turn", given: "Matrix after k = 0 has D[1][2] = 5, D[1][3] = 1, D[3][2] = 2.", steps: [{ say: "D[1][2] after considering k = 3?", blank: true, answer: "min(5, 1 + 2) = 3." }] },
    { type: "trap", wrong: "The loop over k can be innermost.", tempting: "Three nested loops look interchangeable.", whyWrong: "Stage k needs all pairs from stage k − 1.", rule: "k outermost." },
    { type: "trap", wrong: "Floyd–Warshall cannot handle negative edges.", tempting: "Dijkstra cannot.", whyWrong: "It handles them; only negative cycles make distances undefined, and it detects those.", rule: "Check the diagonal." },
    { type: "gate", text: "GATE asks matrix entries after a given k, the final distances, complexity and transitive closure." },
    { type: "recall", cards: [{ q: "FW recurrence", a: "min(D[i][j], D[i][k] + D[k][j])" }, { q: "FW time", a: "Θ(V³)" }, { q: "Negative cycle sign", a: "Negative diagonal" }] },
    { type: "check", questions: [
      { id: "fw1", kind: "NAT", marks: 2, q: "CLRS Floyd–Warshall example: d(1, 3)?", answer: "-3", solution: "1→5→4→3." },
      { id: "fw2", kind: "NAT", marks: 1, q: "Same: d(1, 5)?", answer: "-4", solution: "Direct edge." },
      { id: "fw3", kind: "NAT", marks: 1, q: "D[1][2] = 5, D[1][3] = 1, D[3][2] = 2: D[1][2] after k = 3?", answer: "3", solution: "1 + 2." },
      { id: "fw4", kind: "MCQ", marks: 1, q: "Floyd–Warshall's time complexity?", options: ["Θ(V²)", "Θ(V³)", "Θ(VE)", "Θ(E log V)"], answer: "B", solution: "Three nested loops." },
      { id: "fw5", kind: "MSQ", marks: 2, q: "Which are true?", options: ["It handles negative edges", "A negative diagonal means a negative cycle", "k must be the outer loop", "It needs a priority queue"], answer: "A, B, C", solution: "No queue needed." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Algorithms", sub: "All-pairs shortest paths", href: AL }, { label: "Discrete mathematics", sub: "Transitive closure of relations", href: "/study/sets-relations" }, { label: "Topic 1: Dijkstra", sub: "Single source", href: "/study/shortest-paths" }] },
    { type: "links", prereq: ["DP", "Matrices"], usedIn: ["Routing tables"], cross: ["DM: relations"] },
  ],
};

